    .sronly {
      position: absolute;
      left: -999999px;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      border: 0;
      transition: none;
    }
    .sronly-focusable {
      border: 0;
      clip: rect(0, 0, 0, 0);
      height: 1px;
      left: -999999px;
      margin: -1px;
      overflow: hidden;
      padding: 0;
      position: absolute;
      transition: none;
      width: 1px;
    }
    .sronly-focusable:focus {
      border: auto;
      clip: auto;
      height: auto;
      left: auto;
      margin: auto;
      overflow: auto;
      padding: auto;
      position: relative;
      width: auto;
    }
    .sronly-focusable:focus.skiptomain {
      background: #ffffff;
      clip: auto;
      color: black;
      height: auto;
      left: 5px;
      margin: 0;
      position: absolute;
      top: 5px;
      width: auto;
      z-index: 1;
    }
    
